  str_n29_1_name_desc = "...",
  str_n29_2_name_desc = "Um incêndio começou na cerimônia de inauguração. Você corre para o fogo para resgatar uma garotinha presa. Neste momento, Dark Slayer aparece na sua frente...",
  str_n29_3_name_desc = "...",
  str_n29_4_name_desc = "Kristen começa a investigar a cena do incêndio no armazém do orfanato.",
  str_n29_5_name_desc = "Antes do horário combinado para a troca dos pingentes, Hati tem uma conversa profunda com você na floresta.",
  str_n29_6_name_desc = "Esta é uma floresta perto de Umbraton, um lugar onde vivem os eclipsitas.",
  str_n29_7_name_desc = "...",
  str_n29_8_name_desc = "Hati está profundamente agitado. Memórias de sua infância e de sua mãe passam por sua mente como uma lanterna giratória.",
  str_n29_9_name_desc = "Kristen começa a investigar o antigo orfanato e encontra Grimme, que está sendo atacado por Eclipsites.",
  str_n29_10_name_desc = "...",
  str_n29_11_name_desc = "Você consegue persuadir Kristen reconsiderar se Hati realmente é o incendiário.",
  str_n29_12_name_desc = "Não será fácil para Hati, que é procurado por toda a cidade, para entrar em Umbraton.",
  str_n29_13_name_desc = "Kristen, Hati, e Zenas se reúnem no orfanato. Rancores, antigos e novos, serão resolvidos aqui.",
  str_n29_14_name_desc = "Hati pega de volta o pingente que pertenceu a sua mãe. Ela precisa enfrentar bravamente seu demônio interior antes de revelar o segredo do pingente.",
  str_n29_1_name_desc_long = "A convite de Bethel, você vem a Umbraton para assistir à cerimônia de inauguração do Orfanato Umbraton. Kristen e Zenas, do Lumo Hall of Justice, são os responsáveis pela segurança do evento. Eles dizem que as coisas não têm sido pacíficas em Umbraton recentemente e que um incendiário em série chamado Dark Slayer está vagando por toda parte em Umbraton.",
  str_n29_2_name_desc_long = "O armazém do orfanato está pegando fogo. Você sente que uma garotinha está presa no armazém, então corre para dentro das chamas para salvá-la, independentemente das consequências. Alguém o salva quando a viga do prédio está prestes a cair após ser queimada. Você reconhece que essa pessoa é o Dark Slayer nos pôsteres de procurado.",
  str_n29_3_name_desc_long = "Você acorda no Firefly Bar. O proprietário, Grimme, diz que o nome verdadeiro do Dark Slayer é Hati e que ela não é uma incendiária em série. Depois de ouvir toda a história, você decide ajudar Hati recuperar suas memórias perdidas...",
  str_n29_4_name_desc_long = "Depois de investigar os incêndios nos últimos dois meses, Kristen descobre que as vítimas dos incêndios são todas parentes do antigo orfanato. Ao mesmo tempo, Hati decide trocá-lo pelo pingente que Zenas carrega.",
  str_n29_5_name_desc_long = "Sr. Hamell se recusa a cooperar com a investigação de Kristen, e Zenas conforta o frustrado. Kristen. Por outro lado, você e Hati são atacados por um grande número de Eclipsites na floresta perto de Umbraton. Numa situação crítica, Hati usa seu poder, que sempre foi proibido.",
  str_n29_6_name_desc_long = "...",
  str_n29_7_name_desc_long = "É a hora combinada, e quem veio é o Sr. Hamell?! O Sr. Hamell é assassinado no meio da conversa, e Kristen e Zenas aparecem para prender Hati. A máscara de Zenas cai acidentalmente, revelando uma cicatriz chocante na metade de seu rosto nas sombras.",
  str_n29_8_name_desc_long = "Hati fica profundamente agitado no momento em que Zenas mostra seu rosto. Ela escapa de cena com você, mas é apanhada em memórias de sua infância com sua mãe e não consegue recuperar a compostura. Quando Hati era pequena, ela se sentia um monstro porque sua mãe a proibia de sair de casa e usar seus poderes. Sua mãe até a empurrou para uma lareira.",
  str_n29_9_name_desc_long = "Kristen quer saber o que aconteceu no antigo orfanato, então ela visita dois órfãos que já ficaram lá e agora moram em Lower Lumopolis. No caminho de volta para Umbraton, Kristen salva Grimme de um ataque Eclipsite. Grimme convida Kristen para tomar uma bebida no bar e diz Kristen uma história de meia verdade.",
  str_n29_10_name_desc_long = "Hati retorna ao lugar onde ela morou com sua mãe. Ela fica na lareira para tentar se lembrar do que aconteceu naquela época. a imagem de Kristen atropelar desperta as memórias de Hati. No dia em que a mãe de Hati a empurrou para a lareira, um homem invadiu a casa, matou brutalmente sua mãe e levou embora o precioso pingente.",
  str_n29_11_name_desc_long = "Depois de recuperar suas memórias, Hati alega que Zenas é o verdadeiro culpado que invadiu sua casa, matou sua mãe e pegou o pingente. A cicatriz no rosto de Zenas é a evidência. Kristen discorda, apontando que Zenas conseguiu essas cicatrizes para salvá-la. Os dois lados discutem acaloradamente, então você se propõe a encontrar a evidência crítica, o pingente.",
  str_n29_12_name_desc_long = "...",
  str_n29_13_name_desc_long = "Kristen encontra Zenas no orfanato e implora a Zenas que entregue o pingente para provar sua inocência. Você e Hati apareça e explique seu raciocínio, mas Zenas pensa Kristen tem sido conivente com você o tempo todo. Em uma raiva envergonhada, Zenas leva Kristen refém e quer atribuir todos os crimes a você.",
  str_n29_14_name_desc_long = "Com sua ajuda, Hati supera seu demônio interior e funde o pingente de sua mãe com o seu. Uma foto da família de Hati cai de um espaço escondido no pingente, que é o tesouro mais precioso da mãe de Hati. Com as bênçãos do sol e da menina, Hati dá os primeiros passos rumo a um novo futuro.",
  str_n29_h1_name = "H1 - Sitio",
  str_n29_h2_name = "H2 - Cobra Longa",
  str_n29_h3_name = "H3 - Forma Quebrada",
  str_n29_h4_name = "H4 - Isolamento",
  str_n29_h1_name_desc = "A rota de seu avanço é muito estranha. Alguém poderia estar dirigindo-os? Ou treinando com uma nova tática?",
  str_n29_h2_name_desc = "Por que os inimigos estão formando uma longa fila? Mas não podemos deixar que o número deles aumente assim... Seria melhor atacar um determinado ponto para quebrar a linha?",
  str_n29_h3_name_desc = "A terra está rachada no deserto acidentado e quebrado. Como você pode derrotar seus inimigos rapidamente se tiver problemas para se aproximar deles?",
  str_n29_h4_name_desc = "O terreno dificulta a movimentação do nosso lado. Naturalmente, o inimigo também é afetado. Talvez possamos tirar proveito disso?",
